// pnpm contract:generate — writes shared/api-contracts/generated/ (GD-04, amended 2026-10-25) from the backend's
// generated registry (backend/libs/contract/generated: operations.json, schemas.json, operation-schemas.json,
// enums.ts, errors.ts, role-groups.ts) and, for the server-defined Json<…> shapes only, from the OpenAPI
// components in shared/api-contracts/openapi.yaml. Never writes openapi.yaml (the backend owns it).
// pnpm contract:check — exits 1 when the generated files are stale.
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { parse as parseYaml } from 'yaml';
import { docComment, propertyKey, schemaToTs, type JsonSchema } from './schema-to-ts';

const pwaDir = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const repoDir = join(pwaDir, '..');

export const PATHS = {
  source: join(repoDir, 'backend', 'libs', 'contract', 'generated'),
  openapi: join(repoDir, 'shared', 'api-contracts', 'openapi.yaml'),
  out: join(repoDir, 'shared', 'api-contracts', 'generated'),
};

interface SecTag {
  tag: string;
  args?: string[];
  qualifier?: string;
}
interface Route {
  scope: 'single' | 'me' | 'fleet' | 'org';
  host: 'api' | 'admin-api' | 'auth' | 'storage';
  method: string;
  path: string;
  pathParams: string[];
  security: { principals: SecTag[][]; tags: SecTag[] };
}
interface Operation {
  opId: string;
  module: string;
  summary: string;
  method: string;
  routes: Route[];
  successStatus: number;
  inputEncoding: 'none' | 'json' | 'form' | 'raw';
  errors: { status: number; code: string; detail?: string }[];
}
interface Registry {
  contractVersion: string;
  sourceSha256: string;
  operationCount: number;
  routeCount: number;
  operations: Operation[];
}
interface OperationSchemas {
  query: JsonSchema;
  pathParams: Record<string, JsonSchema>;
  input?: JsonSchema;
  response?: JsonSchema;
  alternateResponses?: Record<string, JsonSchema>;
}

const readJson = <T>(file: string): T => JSON.parse(readFileSync(file, 'utf8')) as T;

function header(sha: string, version: string): string {
  return (
    `// GENERATED by pwa/tools/contract/generate.ts from backend/libs/contract/generated` +
    ` (contract ${version}, Docs/40 sha256 ${sha.slice(0, 12)}). Do not edit; run \`pnpm contract:generate\` in pwa/.\n`
  );
}

/** Last path segment of a $ref ('#/$defs/X', '<id>#/$defs/X', '#/components/schemas/X') or a bare name. */
function refTarget(ref: string): string {
  return ref.slice(ref.lastIndexOf('/') + 1);
}

function collectServerSchemas(value: unknown, into: Set<string>): Set<string> {
  if (Array.isArray(value)) for (const v of value) collectServerSchemas(v, into);
  else if (value && typeof value === 'object') {
    for (const [k, v] of Object.entries(value)) {
      if (k === 'x-server-schema' && typeof v === 'string') into.add(v);
      else collectServerSchemas(v, into);
    }
  }
  return into;
}

function flagsOf(tags: SecTag[]) {
  const has = (t: string) => tags.some((x) => x.tag === t);
  const aal = tags.find((x) => x.tag === 'AAL3') ? 'aal3' : has('AAL2') ? 'aal2' : null;
  return {
    idem: has('IDEM'),
    etag: has('ETAG'),
    aal,
    async: has('ASYNC'),
    att: has('ATT'),
    featureFlags: tags.filter((x) => x.tag === 'FLAG').flatMap((x) => x.args ?? []),
    rateLimit: tags.find((x) => x.tag === 'RL')?.args?.[0] ?? null,
  };
}

function compactTag(t: SecTag): SecTag {
  return { tag: t.tag, ...(t.args && t.args.length > 0 ? { args: t.args } : {}), ...(t.qualifier ? { qualifier: t.qualifier } : {}) };
}

export async function generateFiles(paths = PATHS): Promise<Map<string, string>> {
  const registry = readJson<Registry>(join(paths.source, 'operations.json'));
  const schemas = readJson<{ $defs: Record<string, JsonSchema> }>(join(paths.source, 'schemas.json')).$defs;
  const opSchemas = readJson<{ operations: Record<string, OperationSchemas> }>(join(paths.source, 'operation-schemas.json')).operations;
  const openapi = parseYaml(readFileSync(paths.openapi, 'utf8')) as { components?: { schemas?: Record<string, JsonSchema> } };
  const components = openapi.components?.schemas ?? {};
  const head = header(registry.sourceSha256, registry.contractVersion);

  // Server-defined schemas (Json<Name>) that the registry leaves open; their shapes come from the OpenAPI file.
  const serverNames = [...collectServerSchemas([schemas, opSchemas], new Set<string>())].filter((n) => !(n in schemas)).sort();
  const known = new Set([...Object.keys(schemas), ...serverNames]);
  const refName = (prefix: string) => (ref: string) => {
    const name = refTarget(ref);
    if (!known.has(name)) throw new Error(`Unresolved schema reference ${ref}`);
    return `${prefix}${name}`;
  };

  // --- types.ts
  const typeLines = [head, `// One type per Docs/40 type (schemas.json $defs) plus the server-defined Json<…> shapes.\n`];
  for (const [name, def] of Object.entries(schemas)) {
    const doc = typeof def === 'object' && typeof def.description === 'string' ? docComment(def.description, '') : '';
    typeLines.push(`${doc}export type ${name} = ${schemaToTs(def, { refName: refName('') })};\n`);
  }
  typeLines.push(`// --- Server-defined schemas (OpenAPI components; backend DI-50)\n`);
  // Components may reference further components (e.g. 'InsightPayload.appointment_slot_suggestion'); those are
  // emitted too, with dots turned into underscores. References to Docs/40 types keep their names.
  const componentName = (name: string) => name.replace(/[^\w$]/g, '_');
  const queue = [...serverNames];
  const emitted = new Set<string>();
  const componentRef = (ref: string) => {
    const name = refTarget(ref);
    if (name in schemas) return name;
    if (!(name in components)) throw new Error(`Unresolved OpenAPI reference ${ref}`);
    if (!emitted.has(name) && !queue.includes(name)) queue.push(name);
    return componentName(name);
  };
  while (queue.length > 0) {
    const name = queue.shift() as string;
    emitted.add(name);
    const def = components[name];
    if (def === undefined) {
      typeLines.push(`/** Not described in openapi.yaml. */\nexport type ${componentName(name)} = Record<string, unknown>;\n`);
      continue;
    }
    const doc = typeof def === 'object' && typeof def.description === 'string' ? docComment(def.description, '') : '';
    typeLines.push(`${doc}export type ${componentName(name)} = ${schemaToTs(def, { refName: componentRef })};\n`);
  }

  // --- operations.ts
  const opLines = [head, `import type * as T from './types';\n`];
  opLines.push(
    `export const CONTRACT = ${JSON.stringify({
      version: registry.contractVersion,
      sourceSha256: registry.sourceSha256,
      operationCount: registry.operationCount,
      routeCount: registry.routeCount,
    })} as const;\n`,
  );
  opLines.push(`export type Host = 'api' | 'admin-api' | 'auth' | 'storage';`);
  opLines.push(`export type RouteScope = 'single' | 'me' | 'fleet' | 'org';`);
  opLines.push(
    `export interface SecTag {\n  readonly tag: string;\n  readonly args?: readonly string[];\n  readonly qualifier?: string;\n}`,
  );
  opLines.push(
    `export interface OperationRoute {\n  readonly scope: RouteScope;\n  readonly host: Host;\n  readonly path: string;\n  readonly pathParams: readonly string[];\n  /** ANY ONE alternative applies; every tag inside an alternative applies (40 §0.4). */\n  readonly principals: readonly (readonly SecTag[])[];\n}`,
  );
  opLines.push(
    `export interface OperationMeta {\n  readonly module: string;\n  readonly method: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';\n  readonly successStatus: number;\n  readonly inputEncoding: 'none' | 'json' | 'form' | 'raw';\n  readonly routes: readonly OperationRoute[];\n  /** Sec tags that apply to every route (IDEM, ETAG, AAL2, FLAG(...), RL(...) …). */\n  readonly tags: readonly SecTag[];\n  readonly idem: boolean;\n  readonly etag: boolean;\n  readonly aal: 'aal2' | 'aal3' | null;\n  readonly async: boolean;\n  readonly att: boolean;\n  readonly featureFlags: readonly string[];\n  readonly rateLimit: string | null;\n  readonly query: readonly string[];\n  /** Operation-specific error codes (the common ones of 40 §4.3 apply to all). */\n  readonly errors: readonly string[];\n}\n`,
  );

  const metaEntries: string[] = [];
  const typeEntries: string[] = [];
  for (const op of registry.operations) {
    const tags = op.routes[0]?.security.tags ?? [];
    for (const r of op.routes) {
      if (JSON.stringify(r.security.tags) !== JSON.stringify(tags)) throw new Error(`${op.opId}: routes carry different sec tags`);
    }
    const s = opSchemas[op.opId];
    if (!s) throw new Error(`${op.opId}: missing in operation-schemas.json`);
    const query = s.query as { properties?: Record<string, JsonSchema> };
    const meta = {
      module: op.module,
      method: op.method,
      successStatus: op.successStatus,
      inputEncoding: op.inputEncoding,
      routes: op.routes.map((r) => ({
        scope: r.scope,
        host: r.host,
        path: r.path,
        pathParams: r.pathParams,
        principals: r.security.principals.map((alt) => alt.map(compactTag)),
      })),
      tags: tags.map(compactTag),
      ...flagsOf(tags),
      query: Object.keys(query.properties ?? {}),
      errors: [...new Set(op.errors.map((e) => e.code))],
    };
    metaEntries.push(`  ${JSON.stringify(op.opId)}: ${JSON.stringify(meta)},`);

    // Path parameters: those of every route are required; scope-specific ones (org_id) are optional.
    const all = [...new Set(op.routes.flatMap((r) => r.pathParams))];
    const common = all.filter((p) => op.routes.every((r) => r.pathParams.includes(p)));
    const pathType =
      all.length === 0
        ? 'Record<string, never>'
        : `{ ${all
            .map(
              (p) =>
                `${propertyKey(p)}${common.includes(p) ? '' : '?'}: ${schemaToTs(s.pathParams[p] ?? { type: 'string' }, { refName: refName('T.') })}`,
            )
            .join('; ')} }`;
    const ind = '    ';
    const queryType = schemaToTs(s.query, { refName: refName('T.') }, ind);
    const inputType = s.input === undefined ? 'undefined' : schemaToTs(s.input, { refName: refName('T.') }, ind);
    const responseType = s.response === undefined ? 'null' : schemaToTs(s.response, { refName: refName('T.') }, ind);
    const alternates = Object.entries(s.alternateResponses ?? {}).map(
      ([status, schema]) => `${status}: ${schemaToTs(schema, { refName: refName('T.') }, `${ind}  `)}`,
    );
    typeEntries.push(
      `${docComment(op.summary, '  ')}  ${JSON.stringify(op.opId)}: {\n` +
        `${ind}path: ${pathType};\n${ind}query: ${queryType};\n${ind}input: ${inputType};\n${ind}response: ${responseType};\n` +
        (alternates.length > 0 ? `${ind}alternateResponses: { ${alternates.join('; ')} };\n` : '') +
        `  };`,
    );
  }
  opLines.push(`export const OPERATIONS = {\n${metaEntries.join('\n')}\n} as const satisfies Record<string, OperationMeta>;\n`);
  opLines.push(
    `/** Request and response types per operation (GD-04). */\nexport interface OperationTypes {\n${typeEntries.join('\n')}\n}\n`,
  );
  opLines.push(`export type OperationId = keyof OperationTypes & keyof typeof OPERATIONS;`);
  opLines.push(`export type OperationPath<Id extends OperationId> = OperationTypes[Id]['path'];`);
  opLines.push(`export type OperationQuery<Id extends OperationId> = OperationTypes[Id]['query'];`);
  opLines.push(`export type OperationInput<Id extends OperationId> = OperationTypes[Id]['input'];`);
  opLines.push(`export type OperationResponse<Id extends OperationId> = OperationTypes[Id]['response'];\n`);

  // --- enums.ts, errors.ts, role-groups.ts (re-emitted from the backend's generated modules)
  const load = async <M>(file: string) => (await import(pathToFileURL(join(paths.source, file)).href)) as M;
  const { ENUMS } = await load<{ ENUMS: Record<string, readonly string[]> }>('enums.ts');
  const { ERROR_CODES } = await load<{ ERROR_CODES: Record<string, { status: number; meaning: string; common: boolean }> }>('errors.ts');
  const { ROLE_GROUPS } = await load<{ ROLE_GROUPS: Record<string, unknown> }>('role-groups.ts');
  const enums =
    `${head}\n/** Enumerations of Docs/40 §5. Unknown values from newer servers must be handled as 'unknown' (Appendix C). */\n` +
    `export const ENUMS = {\n${Object.entries(ENUMS)
      .map(([k, v]) => `  ${k}: ${JSON.stringify(v)},`)
      .join(
        '\n',
      )}\n} as const;\n\nexport type EnumName = keyof typeof ENUMS;\nexport type EnumValue<N extends EnumName> = (typeof ENUMS)[N][number];\n`;
  const errors =
    `${head}\nexport interface ErrorCodeInfo {\n  readonly status: number;\n  readonly meaning: string;\n  /** Implicit on every operation (40 §4.3). */\n  readonly common: boolean;\n}\n\n` +
    `export const ERROR_CODES = {\n${Object.entries(ERROR_CODES)
      .map(([k, v]) => `  ${k}: ${JSON.stringify(v)},`)
      .join('\n')}\n} as const satisfies Record<string, ErrorCodeInfo>;\n\nexport type ErrorCode = keyof typeof ERROR_CODES;\n`;
  const roleGroups = `${head}\n/** Role groups of Docs/40 §0.5 (P*, P+, V*, F*, FC, ANY …). */\nexport const ROLE_GROUPS = ${JSON.stringify(ROLE_GROUPS, null, 2)} as const;\n\nexport type RoleGroup = keyof typeof ROLE_GROUPS;\n`;

  const files = new Map<string, string>();
  files.set('types.ts', typeLines.join('\n'));
  files.set('operations.ts', opLines.join('\n'));
  files.set('enums.ts', enums);
  files.set('errors.ts', errors);
  files.set('role-groups.ts', roleGroups);

  // Names exported through index.ts must not collide.
  const exported = new Map<string, string>();
  for (const [file, content] of files) {
    for (const m of content.matchAll(/^export (?:const|type|interface) (\w+)/gm)) {
      const name = m[1] ?? '';
      if (exported.has(name)) throw new Error(`Export ${name} is defined in ${exported.get(name)} and ${file}`);
      exported.set(name, file);
    }
  }
  files.set(
    'index.ts',
    `${head}\nexport * from './types';\nexport * from './operations';\nexport * from './enums';\nexport * from './errors';\nexport * from './role-groups';\n`,
  );
  return files;
}

/** Files that differ from the generated content (missing, changed or extra). */
export function staleFiles(files: Map<string, string>, outDir = PATHS.out): string[] {
  const stale: string[] = [];
  for (const [name, content] of files) {
    const target = join(outDir, name);
    if (!existsSync(target) || readFileSync(target, 'utf8') !== content) stale.push(name);
  }
  if (existsSync(outDir)) for (const f of readdirSync(outDir)) if (!files.has(f)) stale.push(`${f} (extra)`);
  return stale;
}

async function main(argv: string[]): Promise<void> {
  const files = await generateFiles();
  if (argv.includes('--check')) {
    const stale = staleFiles(files);
    if (stale.length > 0) {
      console.error(`shared/api-contracts/generated is stale:\n  ${stale.join('\n  ')}\nRun: pnpm contract:generate`);
      process.exit(1);
    }
    console.log(`shared/api-contracts/generated is up to date (${files.size} files).`);
    return;
  }
  rmSync(PATHS.out, { recursive: true, force: true });
  mkdirSync(PATHS.out, { recursive: true });
  for (const [name, content] of files) writeFileSync(join(PATHS.out, name), content);
  console.log(`Wrote ${files.size} files to shared/api-contracts/generated.`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) await main(process.argv.slice(2));
